1295	 * @brief 解析心率测量（0x2A37）；没有能量则保持 NA。
1296	 */
1297	static void parse_hr_meas(struct sensor_slot *slot, const uint8_t *p,
1298	                         uint16_t len, uint32_t now_ms)
1299	{
1300	  uint8_t flags;
1301	  uint16_t off = 1;
1302	  uint16_t bpm;
1303	  uint16_t energy = 0;
1304	  bool energy_ok = false;
1305	  int8_t contact = -1;
1306	
1307	  if (len < 2)
1308	    {
1309	      return;
1310	    }
1311	
1312	  flags = p[0];
1313	  if ((flags & 0x01) != 0)
1314	    {
1315	      if (len < 3)
1316	        {
1317	          return;
1318	        }
1319	
1320	      bpm = (uint16_t)(p[1] | ((uint16_t)p[2] << 8));
1321	      off = 3;
1322	    }
1323	  else
1324	    {
1325	      bpm = p[1];
1326	      off = 2;
1327	    }
1328	
1329	  if ((flags & 0x02) != 0)
1330	    {
1331	      contact = ((flags & 0x04) != 0) ? 1 : 0;
1332	    }
1333	
1334	  if ((flags & 0x08) != 0 && (uint16_t)(off + 2) <= len)
1335	    {
1336	      energy = (uint16_t)(p[off] | ((uint16_t)p[off + 1] << 8));
1337	      energy_ok = true;
1338	    }
1339	
1340	  if (bpm == 0 || bpm > 250)
1341	    {
1342	      return;
1343	    }
1344	
1345	  if (slot != NULL)
1346	    {
1347	      slot->last_bpm     = bpm;
1348	      slot->last_contact = contact;
1349	      slot->last_energy  = energy;
1350	      slot->energy_ok    = energy_ok;
1351	    }
1352	
1353	  companion_bridge_sensor_set_hr(bpm, now_ms);
1354	}
