1356	/**
1357	 * @brief 解析 CSC 测量（0x2A5B）曲柄增量，换成 RPM。
1358	 */
1359	static void parse_csc_meas(struct sensor_slot *slot, const uint8_t *p,
1360	                           uint16_t len, uint32_t now_ms)
1361	{
1362	  uint8_t  flags;
1363	  uint16_t off = 1;
1364	  uint16_t crank_revs;
1365	  uint16_t crank_time;
1366	
1367	  if (len < 1 || slot == NULL)
1368	    {
1369	      return;
1370	    }
1371	
1372	  flags = p[0];
1373	  if ((flags & 0x01) != 0)
1374	    {
1375	      off = (uint16_t)(off + 6);
1376	    }
1377	
1378	  if ((flags & 0x02) == 0)
1379	    {
1380	      return;
1381	    }
1382	
1383	  if ((uint16_t)(off + 4) > len)
1384	    {
1385	      return;
1386	    }
1387	
1388	  crank_revs = (uint16_t)(p[off] | ((uint16_t)p[off + 1] << 8));
1389	  crank_time = (uint16_t)(p[off + 2] | ((uint16_t)p[off + 3] << 8));
1390	
1391	  if (slot->csc_have)
1392	    {
1393	      uint16_t drev  = (uint16_t)(crank_revs - slot->crank_revs);
1394	      uint16_t dtime = (uint16_t)(crank_time - slot->crank_time);
1395	
1396	      if (drev > 0 && dtime > 0)
1397	        {
1398	          uint32_t rpm = ((uint32_t)drev * 1024u * 60u) / dtime;
1399	
1400	          if (rpm > 0 && rpm < 300)
1401	            {
1402	              slot->last_csc_rpm = (uint16_t)rpm;
1403	              slot->meas_idle    = false;
1404	              companion_bridge_sensor_set_cadence((uint16_t)rpm, now_ms);
1405	            }
1406	        }
1407	    }
1408	
1409	  slot->crank_revs = crank_revs;
1410	  slot->crank_time = crank_time;
1411	  slot->csc_have   = true;
1412	}
