2902	/**
2903	 * @brief 驻留 / 重连冷却之后，按已保存地址连接该槽位。
2904	 *
2905	 * Central 角色使用 BT_LE_CONN_PARAM_DEFAULT。同时只飞一条 HCI 建链
2906	 *（满载时再建易 0x3e）。冷却 800 ms；已有其它 READY 链路时 1500 ms。
2907	 */
2908	static void slot_try_connect(struct sensor_slot *slot, uint32_t now_ms)
2909	{
