2911	
2912	  if (!g_allow_connect && !slot->want_link)
2913	    {
2914	      return;
2915	    }
2916	
2917	  if (g_scan_until_ms != 0)
2918	    {
2919	      return;

2940	    }
2941	
2942	  if (slot->skip_dwell || slot->want_link)
2943	    {
2944	      slot->skip_dwell = false;
2945	    }
2946	  else
2947	    {
2948	      if (sensor_age_ms(now_ms, slot->seen_ms) > SENSOR_DWELL_MS * 4u)
2949	        {
2950	          return;
2951	        }
2952	
2953	      if (sensor_age_ms(now_ms, slot->seen_ms) < SENSOR_DWELL_MS &&
2954	          slot->state_ms == 0)
2955	        {
2956	          slot->state_ms = slot->seen_ms;
2957	          return;
2958	        }
2959	
2960	      if (slot->state_ms != 0 &&
2961	          sensor_age_ms(now_ms, slot->state_ms) < SENSOR_DWELL_MS)
2962	        {
2963	          return;
2964	        }
2965	    }
2966	
2967	  if (g_allow_connect)
2968	    {
2969	      slot->want_link = true;
2970	    }
2971	
2972	  /* 建链前必须确认「本机广播真的停了」（2026-09-20 实机根因）。
2973	   *
2974	   * zblue 的 initiate 路径会先设本机随机地址（LE Set Random Address），而
2975	   * legacy 广播开着时控制器以 Command Disallowed 拒掉它 —— host 在发
2976	   * LE Create Connection **之前**就带着错误返回，应用侧只看到
2977	   * `bt_gattc_connect()` 成功、然后 15 s 超时：实机 HCI 里 0x2005 之后
2978	   * 一条命令都没有，踏频永远连不上。
2979	   *
2980	   * scan 路径早有这个纪律：SENSOR_RADIO_ADV_STOP_WAIT 里等 g_phone_adv_held
2981	   * 才起扫。建链缺的就是这一拍。companion 是**停广播的 HCI 命令回完之后**
2982	   * 才置这个标志（见 companion_hold_le_adv），所以它成立即代表射频上广播
2983	   * 真的没了，此时 initiate 才是合法命令序。
2984	   *
2985	   * 与那里一样**有界**：SENSOR_ADV_STOP_ACK_MS 内没等到就照发并留一行
2986	   * ERROR，不让一个冷标志把建链永久冻死。 */
2987	  if (g_adv_hold_want && !g_phone_adv_held)
2988	    {
2989	      if (slot->adv_wait_ms == 0)
2990	        {
2991	          slot->adv_wait_ms = now_ms != 0 ? now_ms : 1u;
2992	          LOGI("%s wait adv-stop ack before initiate", kind_name(slot->kind));
2993	        }
2994	
2995	      if (sensor_age_ms(now_ms, slot->adv_wait_ms) < SENSOR_ADV_STOP_ACK_MS)
2996	        {
2997	          return;
2998	        }
2999	
3000	      LOGE("%s initiate without adv-stop ack (%u ms), go anyway",
3001	           kind_name(slot->kind),
3002	           (unsigned)sensor_age_ms(now_ms, slot->adv_wait_ms));
3003	    }
3004	
3005	  slot->adv_wait_ms = 0;
3006	
3007	  ret = bt_gattc_connect(slot->gatt, &slot->addr, slot->addr_type);
3008	  if (ret != BT_STATUS_SUCCESS)
3009	    {
3010	      slot->adv_seen = false;
3011	      slot->retry_ms = now_ms + SENSOR_RECONNECT_MS;
3012	      LOGE("%s connect failed: %d, scan again",
3013	           kind_name(slot->kind), (int)ret);
3014	      return;
3015	    }
3016	
3017	  slot->retry_ms = 0;
3018	  slot->state    = SENSOR_CONNECTING;
3019	  slot->state_ms = now_ms;
3020	  {
3021	    char addr[BT_ADDR_STR_LENGTH];
3022	
3023	    bt_addr_ba2str(&slot->addr, addr);
3024	    LOGI("connecting %s %s rssi=%d", kind_name(slot->kind), addr,
3025	         (int)slot->rssi);
3026	  }
3027	}
