1511	static void walk_ad(const uint8_t *ad, uint8_t ad_len, uint32_t now_ms,
1512	                    uint16_t *svc_mask, char *name, size_t namesz)
1513	{
1514	  uint8_t i = 0;
1515	
1516	  *svc_mask = 0;
1517	  if (namesz > 0)
1518	    {
1519	      name[0] = '\0';
1520	    }
1521	
1522	  while ((uint16_t)i + 1 < ad_len)
1523	    {
1524	      uint8_t elen = ad[i];
1525	      uint8_t type;
1526	      uint8_t dlen;
1527	      const uint8_t *d;
1528	      uint8_t k;
1529	
1530	      if (elen == 0 || (uint16_t)i + 1 + elen > ad_len)
1531	        {
1532	          break;
1533	        }
1534	
1535	      type = ad[i + 1];
1536	      d    = ad + i + 2;
1537	      dlen = (uint8_t)(elen - 1);
1538	      i    = (uint8_t)(i + 1 + elen);
1539	
1540	      if (type == BT_AD_UUID16_SOME || type == BT_AD_UUID16_ALL)
1541	        {
1542	          for (k = 0; (uint16_t)k + 1 < dlen; k = (uint8_t)(k + 2))
1543	            {
1544	              uint16_t u = (uint16_t)(d[k] | ((uint16_t)d[k + 1] << 8));
1545	
1546	              if (u == UUID_HRS)
1547	                {
1548	                  *svc_mask |= SENSOR_FEAT_HR;
1549	                }
1550	              else if (u == UUID_CSCS)
1551	                {
1552	                  *svc_mask |= SENSOR_FEAT_CSC;
1553	                }
1554	              else if (u == UUID_CPS)
1555	                {
1556	                  *svc_mask |= SENSOR_FEAT_CPS;
1557	                }
1558	              else if (u == UUID_BAS)
1559	                {
1560	                  *svc_mask |= SENSOR_FEAT_BAT;
1561	                }
1562	            }
1563	        }
1564	      else if (type == BT_AD_SERVICE_DATA16 && dlen >= 2)
1565	        {
1566	          uint16_t u = (uint16_t)(d[0] | ((uint16_t)d[1] << 8));
1567	
1568	          if (u == UUID_HRS)
1569	            {
1570	              *svc_mask |= SENSOR_FEAT_HR;
1571	              parse_hr_meas(NULL, d + 2, (uint16_t)(dlen - 2), now_ms);
1572	            }
1573	          else if (u == UUID_CSCS)
1574	            {
1575	              *svc_mask |= SENSOR_FEAT_CSC;
1576	              parse_csc_meas(&g_slots[SENSOR_KIND_CSC], d + 2,
1577	                             (uint16_t)(dlen - 2), now_ms);
1578	            }
1579	          else if (u == UUID_CPS)
1580	            {
1581	              *svc_mask |= SENSOR_FEAT_CPS;
1582	              parse_cps_meas(NULL, d + 2, (uint16_t)(dlen - 2), now_ms);
1583	            }
1584	          else if (u == UUID_BAS)
1585	            {
1586	              *svc_mask |= SENSOR_FEAT_BAT;
1587	            }
1588	        }
1589	      else if ((type == BT_AD_NAME_COMPLETE || type == BT_AD_NAME_SHORT) &&
1590	               namesz > 1 && dlen > 0)
1591	        {
1592	          size_t n = dlen < namesz - 1 ? dlen : namesz - 1;
1593	
1594	          memcpy(name, d, n);
1595	          name[n] = '\0';
1596	        }
1597	    }
1598	}
